SELECT * FROM tbl_registration_data registration
registration.lastest_registered = 'Y' AND registration.is_deleted = 'N' AND registration.final_status = 'Success'
AND registration.trans_id = #{request.data.transId}
AND registration.create_date >= #{request.data.startCreateDate}::timestamp
AND registration.create_date <= #{request.data.endCreateDate}::timestamp
ORDER BY registration.create_date DESC LIMIT #{limit} OFFSET #{startRow}
